Bun.serve({
  port: 3000,
  hostname: "localhost",
  tls: {
    cert: Bun.file("certs/cert.pem"),
    key: Bun.file("certs/key.pem"),
  },
  async fetch(request) {
    try {
      const url = new URL(request.url);
      if (url.pathname === "/" && request.method === "GET") return page();
      if (url.pathname.startsWith("/api/")) return await api(request, url.pathname);
      return genericError(404);
    } catch {
      // Security §2: production-safe generic failures; no stack traces or sensitive details.
      return genericError(500);
    }
  },
});

/**
 * MFA Enrolment System
 * Single-file Bun HTTPS server and responsive vanilla-JS mobile SPA.
 * Run with: MFA_DEMO_MODE=true bun app.ts
 *
 * Demo/test mode is explicitly isolated behind MFA_DEMO_MODE=true.
 * It uses deterministic values only for academic verification. Secure mode
 * uses cryptographic randomness and never logs raw secrets, codes, or sessions.
