function b32(a: Uint8Array) {
  const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567";
  let out = "", bits = 0, value = 0;
  for (const byte of a) {
    value = (value << 8) | byte;
    bits += 8;
