const encrypt = async (s: string) => {
  const iv = random(12);
  const c = await crypto.subtle.encrypt({ name: "AES-GCM", iv }, key, enc.encode(s));
  return Buffer.from(iv).toString("base64url") + "." + Buffer.from(c).toString("base64url");
