  for(let dy=-1;dy<=7;dy++)for(let dx=-1;dx<=7;dx++){
   const on=dx>=0&&dx<=6&&dy>=0&&dy<=6&&(dx===0||dx===6||dy===0||dy===6||(dx>=2&&dx<=4&&dy>=2&&dy<=4));
